 min_num: integer;
 num: integer;
begin
 min_num := 30001;
 while true do
 begin
 readln(num);
 if num = 0 then
 break;
 if (num mod 3 = 0) and (num < min_num) then
 min_num := num;
 end;
 writeln(min_num);
end.
